local me=0;
local city=CityManager.GetCity(me,Game:GetProperty('JAC_PERSONA_SCENARIO_CITY_A'));
if not city then error('skill target city missing') end;
local wanted={['JAC_PERSONA_DATE_TANEMUNE_BASE']=false,['JAC_PERSONA_DATE_TANEMUNE_PROMOTION_1']=false,['JAC_PERSONA_DATE_TANEMUNE_PROMOTION_2']=false}; local args={['JAC_PERSONA_DATE_TANEMUNE_BASE']={kind='CULTURE',amount=10},['JAC_PERSONA_DATE_TANEMUNE_PROMOTION_1']={kind='AMENITIES',amount=1},['JAC_PERSONA_DATE_TANEMUNE_PROMOTION_2']={kind='GOLD',amount=10}}; local found={};
