    for _,obj in ipairs(GameEffects.GetModifierSubjects(id) or {}) do
      if GameEffects.GetObjectsPlayerId(obj)==me and Locale.Lookup(GameEffects.GetObjectName(obj) or '')==cname then
        found[d.Id]=(found[d.Id] or 0)+1;
      end
    end
  end
end
for mid,active in pairs(wanted) do
  if (found[mid] or 0)~=(active and 1 or 0) then error(mid..' effective city instances: '..tostring(found[mid])..' expected active '..tostring(active)) end;
  local a=args[mid]; local vals={};
  for r in GameInfo.ModifierArguments() do if r.ModifierId==mid then vals[r.Name]=r.Value end end;
  if tonumber(vals.Amount)~=a.amount then error(mid..' amount differs') end;
  if a.kind~='AMENITIES' and a.kind~='MILITARY' and vals.YieldType~='YIELD_'..a.kind then error(mid..' yield differs') end;
end
return 'DATE_TANEMUNE native skill effects verified in city A'

