local wanted={['JAC_PERSONA_DATE_TANEMUNE_BASE']=true,['JAC_PERSONA_DATE_TANEMUNE_PROMOTION_1']=true,['JAC_PERSONA_DATE_TANEMUNE_PROMOTION_2']=true}; local args={['JAC_PERSONA_DATE_TANEMUNE_BASE']={kind='CULTURE',amount=10},['JAC_PERSONA_DATE_TANEMUNE_PROMOTION_1']={kind='AMENITIES',amount=1},['JAC_PERSONA_DATE_TANEMUNE_PROMOTION_2']={kind='GOLD',amount=10}}; local found={};
