  if tonumber(vals.Amount)~=a.amount then error(mid..' amount differs') end;
  if a.kind~='AMENITIES' and a.kind~='MILITARY' and vals.YieldType~='YIELD_'..a.kind then error(mid..' yield differs') end;
end
